CREATE FUNCTION public.validate_personal_preference_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.first_name IS NOT NULL AND length(trim(NEW.first_name)) NOT BETWEEN 1 AND 80 OR NEW.last_name IS NOT NULL AND length(trim(NEW.last_name)) NOT BETWEEN 1 AND 80 OR length(NEW.phone)>32 OR jsonb_typeof(NEW.notification_preferences)<>'object' OR (NEW.notification_preferences->'in_app') IS NULL OR (NEW.notification_preferences->'email') IS NULL OR jsonb_typeof(NEW.notification_preferences->'in_app')<>'boolean' OR jsonb_typeof(NEW.notification_preferences->'email')<>'boolean' OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.notification_preferences) k WHERE k NOT IN ('in_app','email')) THEN RAISE EXCEPTION 'Invalid personal settings'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_personal_preference_update BEFORE INSERT OR UPDATE ON public.user_profiles FOR EACH ROW EXECUTE FUNCTION public.validate_personal_preference_update();
CREATE FUNCTION public.guard_patient_target_eligibility() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.selected_provider_workspace_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.transport_type IS DISTINCT FROM OLD.transport_type) AND NOT EXISTS(SELECT 1 FROM provider_network_profiles p WHERE p.workspace_id=NEW.selected_provider_workspace_id AND EXISTS(SELECT 1 FROM unnest(p.service_types) s WHERE lower(s)=lower(NEW.transport_type) OR NEW.transport_type='gurney' AND lower(s) IN ('stretcher','gurney/stretcher'))) THEN RAISE EXCEPTION 'Selected provider service not compatible'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_patient_target_eligibility BEFORE INSERT OR UPDATE ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.guard_patient_target_eligibility();